import React, { useState, useRef, useEffect } from 'react'
import { useAppContext } from '../../context/AppContext'
import './ChatInput.css'

const SEVERITY_OPTIONS = ['', 'low', 'medium', 'high']
const STATUS_OPTIONS   = ['', 'late_delivery', 'shipping_on_time', 'advance_shipping', 'shipping_canceled']

const SAMPLE_QUERIES = [
  'Supplier delivery delays increasing for critical components',
  'Warehouse inventory approaching stockout levels',
  'Transportation costs spiked unexpectedly',
  'Port congestion impacting shipment schedules',
]

export default function ChatInput({ onSubmit, loading }) {
  const { activeFilters, setActiveFilters } = useAppContext()
  const [query, setQuery]         = useState('')
  const [showFilters, setShowFilters] = useState(false)
  const textareaRef = useRef(null)

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px'
    }
  }, [query])

  const handleSubmit = (e) => {
    e?.preventDefault()
    if (!query.trim() || loading) return
    onSubmit(query.trim(), activeFilters)
    setQuery('')
  }

  const handleKey = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSubmit()
    }
  }

  const handleFilter = (key, val) => setActiveFilters(prev => ({ ...prev, [key]: val }))

  const activeCount = Object.values(activeFilters).filter(Boolean).length

  return (
    <div className="chat-input-wrap">
      {/* Sample queries — shown only when no messages yet */}
      <div className="sample-bar">
        {SAMPLE_QUERIES.map((q, i) => (
          <button key={i} className="sample-chip" onClick={() => setQuery(q)}>
            {q}
          </button>
        ))}
      </div>

      {/* Filters */}
      {showFilters && (
        <div className="filter-bar">
          <div className="filter-grid">
            <div className="filter-field">
              <label>Supplier</label>
              <input type="text" placeholder="e.g. Fan Shop" value={activeFilters.supplier_id || ''} onChange={e => handleFilter('supplier_id', e.target.value)} />
            </div>
            <div className="filter-field">
              <label>Warehouse City</label>
              <input type="text" placeholder="e.g. Chicago" value={activeFilters.warehouse_location || ''} onChange={e => handleFilter('warehouse_location', e.target.value)} />
            </div>
            <div className="filter-field">
              <label>Status</label>
              <select value={activeFilters.shipment_status || ''} onChange={e => handleFilter('shipment_status', e.target.value)}>
                {STATUS_OPTIONS.map(s => <option key={s} value={s}>{s || 'Any'}</option>)}
              </select>
            </div>
            <div className="filter-field">
              <label>Severity</label>
              <select value={activeFilters.severity || ''} onChange={e => handleFilter('severity', e.target.value)}>
                {SEVERITY_OPTIONS.map(s => <option key={s} value={s}>{s || 'Any'}</option>)}
              </select>
            </div>
          </div>
          {activeCount > 0 && (
            <button className="clear-filters" onClick={() => setActiveFilters({ supplier_id: '', warehouse_location: '', shipment_status: '', severity: '' })}>
              Clear filters
            </button>
          )}
        </div>
      )}

      {/* Input row */}
      <form className="input-row" onSubmit={handleSubmit}>
        <button
          type="button"
          className={`filter-btn ${showFilters ? 'active' : ''}`}
          onClick={() => setShowFilters(v => !v)}
          title="Filters"
        >
          ⚙ {activeCount > 0 && <span className="filter-dot" />}
        </button>

        <textarea
          ref={textareaRef}
          className="chat-textarea"
          value={query}
          onChange={e => setQuery(e.target.value)}
          onKeyDown={handleKey}
          placeholder="Ask about supply chain risks... (Enter to send, Shift+Enter for new line)"
          rows={1}
          disabled={loading}
        />

        <button type="submit" className={`send-btn ${loading ? 'loading' : ''}`} disabled={loading || !query.trim()}>
          {loading ? <span className="spinner" /> : '↑'}
        </button>
      </form>
    </div>
  )
}
